def bife_din_text(apps, schema_editor):
    """Proiectele existente: forma de finanțare scrisă în RZ („Fonduri Proprii”, „Bancara”…) devine bifa corespunzătoare.
    Dacă e o singură formă, întreaga valoare RZ îi revine."""
    Proiect = apps.get_model("platforma", "Proiect")
    for p in Proiect.objects.all():
        t = (p.finantare or "").lower()
        forme = [c for c, cheie in (("nerambursabil", "nerambursabil"), ("bancara", "banc"), ("proprii", "propri")) if cheie in t]
        if "europ" in t or " ue" in f" {t}":
            p.fonduri_ue = True
            if "nerambursabil" not in forme:
                forme.append("nerambursabil")
        for c in forme:
            setattr(p, f"fin_{c}", True)
        if len(forme) == 1:
            setattr(p, f"val_{forme[0]}", p.valoare_rz)
        if forme:
            p.save(update_fields=["fonduri_ue"] + [f"fin_{c}" for c in forme] + [f"val_{c}" for c in forme])
